begin;
create table if not exists public.developer_ui_config(id smallint primary key default 1 check(id=1),draft_rules jsonb not null default '[]'::jsonb check(jsonb_typeof(draft_rules)='array'),published_rules jsonb not null default '[]'::jsonb check(jsonb_typeof(published_rules)='array'),updated_by uuid references auth.users(id) on delete set null,published_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now(),published_at timestamptz);
alter table public.developer_ui_config enable row level security;
revoke all on public.developer_ui_config from anon,authenticated;
grant select,insert,update on public.developer_ui_config to authenticated;
drop policy if exists developer_ui_config_read_active on public.developer_ui_config;
create policy developer_ui_config_read_active on public.developer_ui_config for select to authenticated using(public.is_active_member());
drop policy if exists developer_ui_config_insert_developer on public.developer_ui_config;
create policy developer_ui_config_insert_developer on public.developer_ui_config for insert to authenticated with check(public.is_active_developer() and updated_by=auth.uid());
drop policy if exists developer_ui_config_update_developer on public.developer_ui_config;
create policy developer_ui_config_update_developer on public.developer_ui_config for update to authenticated using(public.is_active_developer()) with check(public.is_active_developer() and updated_by=auth.uid());
commit;